package com.keepcalm.placementportal.controller;import com.keepcalm.placementportal.api.PagedResponse;import com.keepcalm.placementportal.models.communication.CommunicationDtos.*;import com.keepcalm.placementportal.service.*;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.data.domain.*;import org.springframework.data.web.PageableDefault;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.Map;
public final class CommunicationController{private CommunicationController(){}@RestController@RequestMapping("/api/v1/notifications")@RequiredArgsConstructor public static class Notifications{private final NotificationService service;@GetMapping public PagedResponse<NotificationDto> list(@PageableDefault(size=20,sort="createdAt",direction=Sort.Direction.DESC)Pageable p){return service.list(p);}@GetMapping("/unread-count")public Map<String,Long> unread(){return service.unread();}@PatchMapping("/{notificationId}/read")public NotificationDto read(@PathVariable Long notificationId){return service.read(notificationId);}@PostMapping("/read-all")public Map<String,Integer> readAll(){return service.readAll();}}@RestController@RequestMapping("/api/v1/announcements")@RequiredArgsConstructor public static class PublicAnnouncements{private final AnnouncementService service;@GetMapping public PagedResponse<AnnouncementDto> list(@PageableDefault(size=20,sort="publishedAt",direction=Sort.Direction.DESC)Pageable p){return service.list(p);}@GetMapping("/{announcementId}")public AnnouncementDto get(@PathVariable Long announcementId){return service.get(announcementId);}}@RestController@RequestMapping("/api/v1/admin/announcements")@RequiredArgsConstructor public static class AdminAnnouncements{private final AnnouncementService service;@PostMapping@ResponseStatus(HttpStatus.CREATED)public AnnouncementDto create(@Valid@RequestBody AnnouncementUpsert r){return service.create(r);}@PutMapping("/{announcementId}")public AnnouncementDto update(@PathVariable Long announcementId,@Valid@RequestBody AnnouncementUpsert r){return service.update(announcementId,r);}@DeleteMapping("/{announcementId}")@ResponseStatus(HttpStatus.NO_CONTENT)public void delete(@PathVariable Long announcementId){service.delete(announcementId);}@PostMapping("/{announcementId}/publish")public AnnouncementDto publish(@PathVariable Long announcementId){return service.publish(announcementId);}}}
